gcZ(){return"\u0420\u0430\u0441\u0448\u044b\u0440\u0446\u0435 \u0441\u0432\u0430\u044e \u0430\u045e\u0434\u044b\u0442\u043e\u0440\u044b\u044e \u0437 \u0434\u0430\u043f\u0430\u043c\u043e\u0433\u0430\u0439 \u0434\u0437\u0456\u045e\u043d\u044b\u0445 \u0433\u0456\u0441\u0442\u043e\u0440\u044b\u0439, \u043f\u0430\u0434\u0437\u044f\u043b\u0456\u0446\u0435\u0441\u044f \u0441\u0432\u0430\u0456\u043c\u0456 \u0434\u0430\u0441\u044f\u0433\u043d\u0435\u043d\u043d\u044f\u043c\u0456 \u0456 \u043d\u043e\u0432\u044b\u043c\u0456 \u043f\u043e\u0441\u043f\u0435\u0445\u0430\u043c\u0456 \u0456 \u0430\u0434\u043a\u0440\u044b\u0432\u0430\u0439\u0446\u0435 \u043d\u043e\u0432\u044b\u0445 \u043b\u044e\u0434\u0437\u0435\u0439."},
gd_(){return"\u0421\u0442\u0432\u0430\u0440\u0430\u0439\u0446\u0435 \u043d\u0435\u043a\u0430\u043b\u044c\u043a\u0456 \u043a\u0440\u044b\u043d\u0456\u0446 \u0434\u0430\u0445\u043e\u0434\u0443, \u043a\u0430\u043b\u0456 \u0432\u044b \u045e\u0441\u043f\u0440\u044b\u043c\u0430\u0435\u0446\u0435 \u0433\u044d\u0442\u0430 \u044f\u043a \u043f\u0440\u0430\u0444\u0435\u0441\u0456\u044e. \u0413\u044d\u0442\u0430 \u043c\u043e\u0436\u0430 \u0431\u044b\u0446\u044c \u0434\u0430\u0434\u0430\u0442\u043a\u043e\u0432\u0430\u044f \u043f\u0440\u0430\u0446\u0430 \u0430\u0431\u043e \u043f\u043e\u045e\u043d\u044b \u043f\u0440\u0430\u0446\u043e\u045e\u043d\u044b \u0434\u0437\u0435\u043d\u044c \u0437 \u0437\u043d\u0430\u0447\u043d\u044b\u043c\u0456 \u0434\u0430\u0445\u043e\u0434\u0430\u043c\u0456."},
gew(){return"\u041a\u0430\u043b\u0456 \u045e \u0432\u0430\u0441 \u0451\u0441\u0446\u044c \u043f\u044b\u0442\u0430\u043d\u043d\u0456 \u0430\u0431 \u043d\u0430\u0448\u0430\u0439 \u043a\u0430\u043c\u043f\u0430\u043d\u0456\u0456, \u0432\u044b \u043c\u043e\u0436\u0430\u0446\u0435 \u043d\u0430\u043f\u0456\u0441\u0430\u0446\u044c \u043d\u0430\u043c \u043f\u0440\u0430\u0437 \u043d\u0430\u0441\u0442\u0443\u043f\u043d\u0443\u044e \u0444\u043e\u0440\u043c\u0443."},
gea(){return"\u041d\u0430\u043f\u0456\u0448\u044b\u0446\u0435 \u043f\u0430\u0432\u0435\u0434\u0430\u043c\u043b\u0435\u043d\u043d\u0435 \u0442\u0443\u0442"},
gdR(a){return"\u0410\u0434\u043f\u0440\u0430\u0432\u0456\u0446\u044c"},
gdS(){return"\u0410\u0434\u043f\u0440\u0430\u045e\u043b\u044f\u0435\u0446\u0446\u0430"},
