gdZ(){return"\u0423\u0432\u044f\u0434\u0437\u0456\u0446\u0435 \u043f\u0430\u0432\u0435\u0434\u0430\u043c\u043b\u0435\u043d\u043d\u0435"},
gde(){return"\u0421\u0430\u0447\u044b\u0446\u0435 \u0437\u0430 \u043d\u0430\u043c\u0456"},
