gdU(){return"\u041f\u0440\u0430\u0433\u0440\u0430\u043c\u043d\u0430\u0435 \u0437\u0430\u0431\u0435\u0441\u043f\u044f\u0447\u044d\u043d\u043d\u0435"},
gdn(){return"\u041d\u044f\u043c\u0430 \u0456\u043d\u0444\u0430\u0440\u043c\u0430\u0446\u044b\u0456 \u043f\u0430 \u0433\u044d\u0442\u044b\u043c \u0437\u0430\u043f\u044b\u0446\u0435"},
gdQ(){return"\u0421\u0430\u0440\u0442\u044b\u0440\u0430\u0432\u0430\u0446\u044c \u043f\u0430 \u043d\u0430\u0437\u0432\u0435"},
gdP(){return"\u0421\u0430\u0440\u0442\u044b\u0440\u0430\u0432\u0430\u0446\u044c \u043f\u0430 \u0430\u043f\u0456\u0441\u0430\u043d\u043d\u0456"},
geC(){return"\u0421\u0430\u0440\u0442\u044b\u0440\u044b\u0440\u0430\u0432\u0430\u0446\u044c \u043f\u0430 \u0456\u043c\u0435\u043d\u0456"},
geD(){return"\u0421\u0430\u0440\u0442\u044b\u0440\u044b\u0440\u0430\u0432\u0430\u0446\u044c \u043f\u0430 \u043f\u0430\u0437\u0456\u0446\u044b\u0456"},
