gd_(){return"\u0410\u043a\u043e \u0433\u043e \u0441\u0444\u0430\u0442\u0438\u0448 \u043e\u0432\u0430 \u043f\u0440\u043e\u0444\u0435\u0441\u0438\u043e\u043d\u0430\u043b\u043d\u043e, \u043c\u043e\u0436\u0435\u0448 \u0434\u0430 \u0441\u043e\u0437\u0434\u0430\u0434\u0435\u0448 \u043f\u043e\u0432\u0435\u045c\u0435 \u0438\u0437\u0432\u043e\u0440\u0438 \u043d\u0430 \u043f\u0440\u0438\u0445\u043e\u0434. \u041e\u0432\u0430 \u043c\u043e\u0436\u0435 \u0434\u0430 \u0431\u0438\u0434\u0435 \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u043d\u0430 \u0440\u0430\u0431\u043e\u0442\u0430 \u0438\u043b\u0438 \u043f\u043e\u043b\u043d\u043e \u0440\u0430\u0431\u043e\u0442\u043d\u043e \u0432\u0440\u0435\u043c\u0435 \u0441\u043e \u0437\u043d\u0430\u0447\u0438\u0442\u0435\u043b\u043d\u0438 \u043f\u0440\u0438\u0445\u043e\u0434\u0438."},
gew(){return"\u0410\u043a\u043e \u0438\u043c\u0430\u0442\u0435 \u043f\u0440\u0430\u0448\u0430\u045a\u0430 \u0432\u043e \u0432\u0440\u0441\u043a\u0430 \u0441\u043e \u043d\u0430\u0448\u0430\u0442\u0430 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0458\u0430, \u043c\u043e\u0436\u0435\u0442\u0435 \u0434\u0430 \u043d\u0438 \u043f\u0438\u0448\u0435\u0442\u0435 \u043f\u0440\u0435\u043a\u0443 \u0441\u043b\u0435\u0434\u043d\u0430\u0442\u0430 \u0444\u043e\u0440\u043c\u0430."},
gea(){return"\u041d\u0430\u043f\u0438\u0448\u0438 \u0458\u0430 \u043f\u043e\u0440\u0430\u043a\u0430\u0442\u0430 \u0442\u0443\u043a\u0430"},
