gdP(){return"\u0420\u0435\u0437\u0443\u043b\u0442\u0430\u0442\u0438 \u0441\u043f\u043e\u0440\u0435\u0434 \u043e\u043f\u0438\u0441"},
geC(){return"\u0420\u0435\u0437\u0443\u043b\u0442\u0430\u0442\u0438 \u0441\u043f\u043e\u0440\u0435\u0434 \u0438\u043c\u0435"},
geD(){return"\u0420\u0435\u0437\u0443\u043b\u0442\u0430\u0442\u0438 \u0441\u043f\u043e\u0440\u0435\u0434 \u043f\u043e\u0437\u0438\u0446\u0438\u0458\u0430"},
gdN(){return"\u041d\u0438\u0448\u0442\u043e \u043d\u0435 \u0435 \u043d\u0430\u0458\u0434\u0435\u043d\u043e \u0432\u043e \u043e\u0432\u0430\u0430 \u0441\u0435\u043a\u0446\u0438\u0458\u0430"},
gcS(a){return"\u041f\u0440\u0435\u0431\u0430\u0440\u0443\u0432\u0430\u045a\u0435"},
ge8(){return"\u043f\u0440\u0435\u0434"},
gek(){return"\u041f\u043e\u0432\u0440\u0437\u0438 \u0441\u0435"},
