geJ(a){return"\u0412\u0435\u0440\u0441\u0438\u044f"},
gen(a){return"\u0421\u043a\u0430\u0447\u0430\u0442\u044c"},
geq(){return"\u042d\u0442\u043e\u0442 email \u043d\u0435\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u0435\u043d"},
