gda(){return"T\xfcm haklar\u0131 sakl\u0131d\u0131r"},
gcI(){return"Giri\u015f Yap"},
gdL(){return"Devam Et"},
gex(){return"Edhomy hesab\u0131 olu\u015fturduysan\u0131z, video g\xf6r\xfc\u015fmelerine kat\u0131lmak i\xe7in giri\u015f yapabilirsiniz"},
gdl(){return"Y\xfckleniyor"},
gdK(a){return"Ba\u011flant\u0131"},
